    /// Die Fläche, die eine Einheit in der Welt einnimmt: die Figur steht mit den
    /// Füßen auf ihrer Position und ist 24 Einheiten breit und hoch – so, wie
    /// DrawUnits sie zeichnet. Auswahl per Klick und per Rahmen prüfen dagegen.
    /// </summary>
    private static Rectangle UnitWorldRect(Unit unit)
        => new Rectangle((int)(unit.Position.X - 12), (int)(unit.Position.Y - 24), 24, 24);

2. In SelectUnitsInRectangle: die Zeilen 'var unitRect = new Rectangle(' und '(int)(u.Position.X - 8), (int)(u.Position.Y - 8), 16, 16);' werden zu 'var unitRect = UnitWorldRect(u);'.

3. Die ganze Methode SelectSingleUnit (bisher mit dem Parameter 'Vector2 gridPos') wird ersetzt durch:
    private void SelectSingleUnit(Vector2 worldPos)
    {
        // Clear previous selection
        foreach (var unit in selectedUnits)
            unit.IsSelected = false;
        selectedUnits.Clear();

        // Die Einheit, deren Figur unter dem Zeiger liegt. Überlappen sich zwei,
        // gewinnt die zuletzt gezeichnete, also die vorderste.
        var point = new Point((int)worldPos.X, (int)worldPos.Y);
        var u = units.LastOrDefault(u => u.OwnerId == 0 && UnitWorldRect(u).Contains(point));

        if (u != null)
        {
            selectedUnits.Add(u);
            u.IsSelected = true;
        }
    }

