ERSATZ:
    /// <summary>
    /// Ob das Haus mit der linken oberen Ecke auf <paramref name="cell"/> Platz
    /// hat: freie, bebaubare Fläche (TileMap.CanPlaceBuilding), schon einmal
    /// gesehen und ohne Einheit darauf.
    /// </summary>
    private bool CanPlaceHouse(Vector2 cell)
    {
        int x = (int)cell.X, y = (int)cell.Y;
        if (!tileMap.CanPlaceBuilding(x, y, HOUSE_SIZE))
            return false;
        for (int bx = x; bx < x + HOUSE_SIZE; bx++)
            for (int by = y; by < y + HOUSE_SIZE; by++)
                if (!tileMap.IsTileExplored(bx, by, 0))
                    return false;
        return !units.Any(u =>
        {
            var c = WorldToGrid(u.Position);
            return c.X >= x && c.X < x + HOUSE_SIZE && c.Y >= y && c.Y < y + HOUSE_SIZE;
        });
    }

    /// <summary>
    /// Setzt ein Haus für Spieler 0 mit der linken oberen Ecke auf
    /// <paramref name="cell"/> und bezahlt es. Passt es nicht hin oder reicht
    /// das Holz nicht, bleibt der Setzmodus an und ein Hinweis erscheint.
    /// </summary>
    private void PlaceHouse(Vector2 cell)
    {
        if (!CanPlaceHouse(cell))
        {
            ShowHudMessage("Hier kann nicht gebaut werden");
            return;
        }
        if (!player1.Resources.PayCost(HouseCost))
        {
            ShowHudMessage($"Nicht genug Holz ({HouseCost[Resource.Wood]})");
            return;
        }
        tileMap.AddBuilding((int)cell.X, (int)cell.Y, "Haus", 0, HOUSE_SIZE);
        placingHouse = false;
    }

