    /// <summary>Das Gebäude, das die Kachel bedeckt, oder null.</summary>
    private Building BuildingAt(Vector2 cell)
        => tileMap.Buildings.FirstOrDefault(b => cell.X >= b.X && cell.X < b.X + b.Width
