        float b = (cursor.Y - r.Top) * 2f / k;
        float gx = MathHelper.Clamp((a + b) / 2f, 0f, tileMap.Width);
        float gy = MathHelper.Clamp((b - a) / 2f, 0f, tileMap.Height);
