    private void DrawMinimap(SpriteBatch sb, Rectangle r)
    {
        sb.Draw(px, new Rectangle(r.Left - 2, r.Top - 2, r.Width + 4, r.Height + 4),
                new Color(30, 22, 12));
        sb.Draw(px, r, new Color(12, 12, 12));

