    private void DrawMinimapLine(SpriteBatch sb, Vector2 a, Vector2 b, Color color)
    {
        var d = b - a;
        float length = d.Length();
        if (length < 0.5f)
            return;
        sb.Draw(px, a, null, color, MathF.Atan2(d.Y, d.X), Vector2.Zero,
                new Vector2(length, 1f), SpriteEffects.None, 0f);
